import Link from "next/link";
import { ArrowUpRight } from "lucide-react";
import styles from "./templates.module.css";

export function FreePlanSidebar({ used }: { used: boolean }) {
  return (
    <aside className={`grid gap-4`} aria-label="Free plan">
      <section
        className={`${styles.planPanel} [background:var(--tpl-card)] [border:1px_solid_var(--tpl-line)] rounded-[22px] min-w-0 p-5.5 panel`}
        aria-labelledby="free-template-plan-title"
      >
        <span
          className={`block text-[var(--tpl-muted)] mb-2 [font:500_11.5px_var(--font-jetbrains),_monospace] tracking-[0.12em] uppercase`}
        >
          Free plan
        </span>
        <h2
          id="free-template-plan-title"
          className="text-[19px] font-bold tracking-[-0.025em] leading-[1.25]"
        >
          One template. Every introduction.
        </h2>
        <p className="text-[var(--tpl-muted)] text-[14px] mt-2">
          Your plan includes one reusable template. Edit it anytime and
          personalise it for every recipient.
        </p>
        <meter
          className={`${styles.meter} block [appearance:none] w-full h-1.5 [border:0] rounded-[4px] [background:var(--tpl-line)] mt-3.5 overflow-hidden`}
          min={0}
          max={1}
          value={used ? 1 : 0}
          aria-label={`${used ? 1 : 0} of 1 templates used`}
        />
        <p className="text-[var(--tpl-muted)] text-[12.5px] mt-2">
          {used ? 1 : 0} of 1 templates used
        </p>
      </section>
      <section
        className={`${styles.upgradePanel} p-5.5 [border:1px_solid_var(--tpl-upgrade-line)] rounded-[22px] [background:linear-gradient(var(--card),_var(--card))_padding-box,_var(--tpl-gradient)_border-box] shadow-[var(--tpl-upgrade-shadow)] panel`}
      >
        <h2 className="text-[19px] font-bold tracking-[-0.025em] leading-[1.25]">
          Need more templates?
        </h2>
        <p className="text-[var(--tpl-muted)] text-[14px] mt-2">
          Premium includes unlimited saved templates.
        </p>
        <Link
          className={`${styles.primary} upgrade-shine relative isolate overflow-hidden mt-4 w-full button-interaction primary-action [background:var(--primary-action-gradient)] text-[var(--primary-action-ink)] shadow-none inline-flex items-center justify-center gap-2 py-[11px] px-5.5 min-h-11 rounded-full font-bold text-[14px] [background:var(--primary-action-gradient)] text-[var(--primary-action-ink)] shadow-none no-underline shrink-0`}
          href="/pricing"
        >
          View Premium plan
          <ArrowUpRight size={17} aria-hidden="true" />
        </Link>
      </section>
    </aside>
  );
}
